// Generated by Cypress Author on 2026-10-15
// Drive object visibility: making a file public needs a confirmation that the
// server decides on, and making it private does not.
//
// Each test uploads its own uniquely named file and does not depend on another
// test. Waiting on the user happens only in the browser, so the checks here also
// confirm the dialog opens, stays open, and recovers without any job pending.

import { isRecord } from "../tasks/narrow.js";
import { jobIdFrom, waitForJob } from "../support/jobs.js";
import {
  SMALL_IMAGE,
  actionsButton,
  bucketNameFrom,
  namedFixture,
  objectsGrid,
  openActions,
  openDrive,
  readOwnRow,
  rowFor,
  uploadThroughDialog,
} from "../support/driveObjects.js";

const visibilityRoute = {
  method: "POST",
  url: /\/api\/storage\/buckets\/[^/]+\/objects\/visibility$/,
} as const;

function dialog() {
  return cy.get("[data-cy='confirm_dialog']", { timeout: 20000 });
}

/** Opens a private file's menu and starts "Make public…". */
function startMakePublic(fileName: string) {
  openActions(fileName);
  cy.get("[data-cy='dStorage_make_public']").should("be.visible").click();
  dialog().should("be.visible");
}

/** Resolves with the bucket the page is using, taken from its first list request. */
function bucketFromListRequest(): Cypress.Chainable<string> {
  return cy.get<{ request: { url: string } }>("@listObjects").then((i) => bucketNameFrom(i.request.url));
}

function badgeFor(fileName: string) {
  return rowFor(fileName).contains(/^(Public|Private)$/);
}

describe("drive object visibility", () => {
  beforeEach(() => {
    // Desktop width shows the table; the same menu is shared by list and tiles.
    cy.viewport(1440, 900);
  });

  it("owner makes a file public and then private again → badge and menu flip, and only making public asks first", () => {
    cy.uniqueRecordName("vis-flip").then((marker) => {
      const file = namedFixture(SMALL_IMAGE, marker);
      openDrive(0, "mine");
      uploadThroughDialog(file);
      cy.intercept(visibilityRoute).as("setVisibility");
      cy.intercept({ method: "POST", url: "**/api/confirmations" }).as("confirmOperation");

      badgeFor(file.fileName).should("have.text", "Private");

      startMakePublic(file.fileName);
      // The first job has finished by now: the dialog is waiting on the person alone.
      cy.wait("@setVisibility").then((interception) => {
        expect(interception.request.body).to.deep.include({ visibility: "public" });
        expect(interception.response?.statusCode).to.eq(202);
        return waitForJob(jobIdFrom(interception.response?.body)).then((job) => {
          expect(job.status).to.eq("completed");
          expect(isRecord(job.result) && job.result.kind).to.eq("confirmation_required");
        });
      });
      cy.get("[data-cy='confirm_dialog_confirm']", { timeout: 20000 }).should("be.enabled");
      cy.get("[data-cy='confirm_dialog']", { timeout: 20000 }).should("have.attr", "aria-busy", "false");
      // Nothing was committed yet.
      badgeFor(file.fileName).should("have.text", "Private");

      cy.get("[data-cy='confirm_dialog_confirm']").click();
      cy.wait("@confirmOperation", { timeout: 60000 }).then((interception) => {
        expect(interception.response?.statusCode).to.eq(202);
        return waitForJob(jobIdFrom(interception.response?.body)).then((job) => {
          expect(isRecord(job.result) && job.result.kind).to.eq("visibility_changed");
        });
      });
      cy.get("[data-cy='confirm_dialog']").should("not.exist");
      badgeFor(file.fileName).should("have.text", "Public");

      // The menu now offers the opposite action, and making private asks nothing.
      openActions(file.fileName);
      cy.get("[data-cy='dStorage_make_public']").should("not.exist");
      cy.get("[data-cy='dStorage_make_private']").should("be.visible").click();
      cy.wait("@setVisibility").then((interception) => {
        expect(interception.request.body).to.deep.include({ visibility: "private" });
        return waitForJob(jobIdFrom(interception.response?.body)).then((job) => {
          expect(isRecord(job.result) && job.result.kind).to.eq("visibility_changed");
        });
      });
      cy.get("[data-cy='confirm_dialog']").should("not.exist");
      badgeFor(file.fileName).should("have.text", "Private");
    });
  });

  it("owner cancels the confirmation with the button, then with Escape → file stays private and focus returns to the actions button", () => {
    cy.uniqueRecordName("vis-cancel").then((marker) => {
      const file = namedFixture(SMALL_IMAGE, marker);
      openDrive(0, "mine");
      uploadThroughDialog(file);
      cy.intercept({ method: "POST", url: "**/api/confirmations" }).as("confirmOperation");

      // Cancel button.
      startMakePublic(file.fileName);
      cy.get("[data-cy='confirm_dialog_confirm']", { timeout: 20000 }).should("be.enabled");
      // The safe choice takes focus first.
      cy.focused().should("have.attr", "data-cy", "confirm_dialog_cancel");
      cy.get("[data-cy='confirm_dialog_cancel']").click();
      dialog().should("not.exist");
      actionsButton(file.fileName).should("have.focus");
      badgeFor(file.fileName).should("have.text", "Private");

      // Escape.
      startMakePublic(file.fileName);
      cy.get("[data-cy='confirm_dialog_confirm']", { timeout: 20000 }).should("be.enabled");
      cy.get("body").type("{esc}");
      cy.get("[data-cy='confirm_dialog']").should("not.exist");
      actionsButton(file.fileName).should("have.focus");
      badgeFor(file.fileName).should("have.text", "Private");

      // Neither dismissal submitted a confirmation.
      cy.get("@confirmOperation.all").should("have.length", 0);
    });
  });

  it("confirmation expires on screen → Make public is disabled, Refresh confirmation issues a fresh one, and confirming works", () => {
    cy.uniqueRecordName("vis-expire").then((marker) => {
      const file = namedFixture(SMALL_IMAGE, marker);
      openDrive(0, "mine");
      uploadThroughDialog(file);

      // Shorten only the first challenge the page receives. The server's own
      // five-minute rule is covered by the database tests; this checks what the
      // dialog does when the time arrives, without a five-minute wait.
      let shortened = false;
      cy.intercept({ method: "GET", url: /\/api\/jobs\/[^/?]+$/ }, (req) => {
        req.continue((res) => {
          const body: unknown = res.body;
          if (
            !shortened &&
            isRecord(body) &&
            isRecord(body.result) &&
            body.result.kind === "confirmation_required"
          ) {
            shortened = true;
            body.result.expiresAt = new Date(Date.now() + 2500).toISOString();
          }
        });
      });
      cy.intercept(visibilityRoute).as("setVisibility");

      startMakePublic(file.fileName);
      cy.get("[data-cy='confirm_dialog_confirm']", { timeout: 20000 }).should("be.enabled");

      // It expires by itself, stays open, and says so without any countdown.
      cy.get("[data-cy='confirm_dialog_refresh']", { timeout: 15000 }).should("be.enabled");
      cy.get("[data-cy='confirm_dialog_confirm']").should("be.disabled");
      cy.get("[data-cy='confirm_dialog_status']").should("contain.text", "expired");
      dialog().invoke("text").should("not.match", /\b\d+\s*(seconds?|secs?|minutes?|mins?)\b|remaining|countdown|time left/i);

      cy.get("[data-cy='confirm_dialog_refresh']").click();
      // A second, separate initiation was requested.
      cy.get("@setVisibility.all").should("have.length", 2);
      cy.get("[data-cy='confirm_dialog_confirm']", { timeout: 20000 }).should("be.enabled");
      cy.get("[data-cy='confirm_dialog_refresh']").should("not.exist");

      cy.get("[data-cy='confirm_dialog_confirm']").click();
      cy.get("[data-cy='confirm_dialog']", { timeout: 60000 }).should("not.exist");
      badgeFor(file.fileName).should("have.text", "Public");
    });
  });

  it("owner views the public tab → public file offers no visibility actions", () => {
    cy.uniqueRecordName("vis-tabs").then((marker) => {
      const file = namedFixture(SMALL_IMAGE, marker);
      openDrive(0, "mine");
      uploadThroughDialog(file);
      cy.intercept({ method: "POST", url: "**/api/confirmations" }).as("confirmOperation");

      startMakePublic(file.fileName);
      cy.get("[data-cy='confirm_dialog_confirm']", { timeout: 20000 }).should("be.enabled").click();
      cy.wait("@confirmOperation", { timeout: 60000 });
      cy.get("[data-cy='confirm_dialog']").should("not.exist");

      // The same file, listed on the public tab, has no visibility actions.
      cy.visit("/drive/public");
      cy.waitForClerkLoaded();
      objectsGrid().should("contain", file.fileName);
      openActions(file.fileName);
      cy.get("[role='menuitem']").should("contain.text", "Download");
      cy.get("[data-cy='dStorage_make_public']").should("not.exist");
      cy.get("[data-cy='dStorage_make_private']").should("not.exist");
    });
  });

  it("another user changes someone else's file through the API → rejected as forbidden, and nothing changes", () => {
    cy.uniqueRecordName("vis-forged").then((marker) => {
      const file = namedFixture(SMALL_IMAGE, marker);
      openDrive(0, "mine");
      uploadThroughDialog(file);

      bucketFromListRequest().then((bucket) => {
        readOwnRow(bucket, file.fileName).then((before) => {
          expect(before.isPublic).to.eq(false);

          // The second user knows the id and revision and forges the request.
          cy.signInAsUser(1);
          const attempt = (visibility: "public" | "private") =>
            cy
              .request({
                method: "POST",
                url: `/api/storage/buckets/${encodeURIComponent(bucket)}/objects/visibility`,
                headers: { "Idempotency-Key": `forged-${visibility}-${marker}` },
                body: {
                  target: { type: "storage_object", id: before.storageObjectId },
                  expectedRevision: before.configVersion,
                  visibility,
                },
              })
              .then((response) => {
                expect(response.status).to.eq(202);
                return waitForJob(jobIdFrom(response.body));
              })
              .then((job) => {
                // A refusal is a normal, completed answer, not a server error.
                expect(job.status).to.eq("completed");
                expect(job.result).to.deep.eq({ kind: "rejected", reason: "forbidden" });
              });
          attempt("public");
          attempt("private");

          // The owner still sees an unchanged private file.
          cy.signInAsUser(0);
          readOwnRow(bucket, file.fileName).then((after) => {
            expect(after.isPublic).to.eq(false);
            expect(after.configVersion).to.eq(before.configVersion);
          });
        });
      });
    });
  });

  it("owner changes a file's visibility twice → the stored bytes are identical every time", () => {
    cy.uniqueRecordName("vis-bytes").then((marker) => {
      const file = namedFixture(SMALL_IMAGE, marker);
      openDrive(0, "mine");
      uploadThroughDialog(file);
      cy.intercept({ method: "POST", url: "**/api/confirmations" }).as("confirmOperation");
      cy.intercept(visibilityRoute).as("setVisibility");

      const downloadedBytes = (bucket: string, key: string) =>
        cy
          .request(`/api/storage/buckets/${encodeURIComponent(bucket)}/objects/download?key=${encodeURIComponent(key)}`)
          .then((response) => waitForJob(jobIdFrom(response.body)))
          .then((job) => {
            expect(job.status).to.eq("completed");
            if (!isRecord(job.result) || typeof job.result.url !== "string") {
              throw new Error("download result has no url");
            }
            return cy.request({ url: job.result.url, encoding: "binary" });
          })
          .then((response) => Cypress.Buffer.from(String(response.body), "binary"));

      bucketFromListRequest().then((bucket) => {
        readOwnRow(bucket, file.fileName).then((row) => {
          cy.readFile(SMALL_IMAGE, null).then((original) => {
            downloadedBytes(bucket, row.s3ObjectKey).then((before) => {
              expect(Cypress.Buffer.from(original).equals(before), "bytes before").to.eq(true);
            });

            startMakePublic(file.fileName);
            cy.get("[data-cy='confirm_dialog_confirm']", { timeout: 20000 }).should("be.enabled").click();
            cy.wait("@confirmOperation", { timeout: 60000 });
            cy.get("[data-cy='confirm_dialog']").should("not.exist");
            openActions(file.fileName);
            cy.get("[data-cy='dStorage_make_private']").click();
            cy.wait("@setVisibility");
            badgeFor(file.fileName).should("have.text", "Private");

            downloadedBytes(bucket, row.s3ObjectKey).then((after) => {
              expect(Cypress.Buffer.from(original).equals(after), "bytes after").to.eq(true);
            });
          });
        });
      });
    });
  });
});
